    "title": "Kinh Pháp Cú — Phẩm 1: Song Yếu (Tâm Làm Chủ)",
    "sanskritOrPaliTitle": "Dhammapada — Yamakavagga",
    "category": "Thiền Kệ & Lời Phật Dạy",
