      {
        "title": "III.2. Kinh Pháp Cú — Phẩm 1: Song Yếu (Tâm Làm Chủ) — Pháp Nghĩa Thù Thắng",
        "paragraphs": [
          "3. Nó mắng tôi, đánh tôi, Nó thắng tôi, cướp tôi Ai ôm hiềm hận ấy, Hận thù không thể nguôi.",
          "4. Who bears within no enmity: \"He has abused and beaten me, defeated me and plundered me\", hate is quite allayed for them.",
          "4. Nó mắng tôi, đánh tôi, Nó thắng tôi, cướp tôi Không ôm hiềm hận ấy, Hận thù được tự nguôi.",
          "5. Never here by enmity are those with enmity allayed, they are allayed by amity, this is the timeless Truth.",
          "5. Với hận diệt hận thù, Ðời này không có được. Không hận diệt hận thù, Là định luật ngàn thu.",
          "6. Still others do not understand that we must perish in this world, those who understand this, their quarrels are allayed."
        ]
      },
      {
        "title": "III.3. Kinh Pháp Cú — Phẩm 1: Song Yếu (Tâm Làm Chủ) — Hành Trì & Quán Chiếu",
        "paragraphs": [
          "6. Và người khác không biết, Chúng ta đây bị hại. Chỗ ấy, ai hiểu được Tranh luận được lắng êm.",
          "7. One who beauty contemplates, whose faculties are unrestrained, in food no moderation knows, is languid, who is indolent: that one does Mara overthrow as wind a tree of little strength.",
          "7. Ai sống nhìn tịnh tướng, Không hộ trì các căn, ăn uống thiếu tiết độ, biếng nhác, chẳng tinh cần. Ma uy hiếp kẻ ấy, như cây yếu trước gió.",
          "8. One who foulness contemplates, whose faculties are well-restrained, in food does moderation know, is full of faith, who's diligent: that one no Mara overthrows, as wind does not a rocky mount.",
          "8. Ai sống quán bất tịnh, Khéo hộ trì các căn, ăn uống có tiết độ, Có lòng tin, tinh cần, Ma không uy hiếp được, Như núi đá, trước gió."
        ]
      }
