        "title": "III.2. Kinh Pháp Cú — Phẩm 2: Không Phóng Dật — Pháp Nghĩa Thù Thắng",
        "paragraphs": [
          "22. Biết rõ sai biệt ấy, Người trí không phóng dật, Hoan hỷ, không phóng dật, An vui hạnh bậc Thánh.",
          "23. They meditate persistently, constantly they firmly strive, the steadfast to Nibbana reach, the Unexcelled Secure from bonds.",
          "23. Người hằng tu thiền định, Thường kiên trì tinh tấn. Bậc trí hưởng Niết Bàn, Ðạt an tịnh vô thượng.",
          "24. Assiduous and mindful, pure kamma making, considerate, restrained, by Dhamma living, and in heedfulness, for one such spreads reknown.",
          "24. Nỗ lực, giữ chánh niệm, Tịnh hạnh, hành thận trọng Tự điều, sống theo pháp, Ai sống không phóng dật, Tiếng lành ngày tăng trưởng.",
          "25. By energy and heedfulness, by taming and by self-control, the one who's wise should make as isle no flood can overwhelm."
        ]
