    "toanVan": [
      {
        "title": "III.1. Kinh Pháp Cú — Phẩm 15: An Lạc (Sống Không Hận Thù) — Chánh Văn Khai Thị",
        "paragraphs": [
          "Buddhasasana Home Page This document is written in Vietnamese, with Unicode Times font",
          "Kinh Pháp Cú Vietnamese translation by Bhikkhu Thích Minh Châu Sài Gòn, Việt Nam, 1996",
          "197. We the unhating live happily midst the haters, among the hating humans from hatred dwell we free.",
          "197. Vui thay, chúng ta sống, Không hận, giữa hận thù! Giữa những người thù hận, Ta sống, không hận thù!",
          "198. We who are healthy live happily midst the unhealthy, among unhealthy humans from ill-health dwell we free.",
          "198. Vui thay, chúng ta sống, Không bệnh giữa ốm đau! Giữa những người bệnh hoạn, Ta sống, không ốm đau."
        ]
      },
      {
        "title": "III.2. Kinh Pháp Cú — Phẩm 15: An Lạc (Sống Không Hận Thù) — Pháp Nghĩa Thù Thắng",
        "paragraphs": [
          "199. We the unfrenzied live happily midst the frenzied, among the frenzied humans from frenzy dwell we free.",
          "199. Vui thay, chúng ta sống, Không rộn giữa rộn ràng; Giữa những người rộn ràng, Ta sống, không rộn ràng.",
          "200. We for whom there's nought live indeed so happily, joy-sustained we'll be like resplendent gods.",
          "200. Vui thay chúng ta sống, Không gì, gọi của ta. Ta sẻ hưởng hỷ lạc, Như chư thiên Quang Âm.",
          "201. Victory gives rise to hate, those defeated lie in pain, happily rest the Peaceful surrendering victory-defeat.",
          "201. Chiến thắng sinh thù oán, Thất bại chịu khổ đau, Sống tịch tịnh an lạc. Bỏ sau mọi thắng bại."
        ]
      },
      {
        "title": "III.3. Kinh Pháp Cú — Phẩm 15: An Lạc (Sống Không Hận Thù) — Hành Trì & Quán Chiếu",
        "paragraphs": [
          "202. There's no fire like lust, no evil like aversion, no dukkha like the aggregates, no higher bliss than Peace.",
          "202. Lửa nào sánh lửa tham ? Ác nào bằng sân hận ? Khổ nào sánh khổ uẩn, Lạc nào bằng tịnh lạc.",
          "203. Hunger is the greatest ill, the greatest dukkha - conditionedness, knowing this reality at it is: Nibbana bliss supreme.",
          "203. Ðói ăn, bệnh tối thượng, Các hành, khổ tối thượng, Hiểu như thực là vậy, Niết bàn, lạc tối thượng.",
          "204. Health's the greatest gain, contentment, best of wealth, trusting's best of kin, Nibbana bliss supreme.",
          "204. Không bệnh, lợi tối thượng, Biết đủ, tiền tối thượng. Thành tín đối với nhau, Là bà con tối thượng, Niết bàn, lạc tối thượng."
        ]
      }
    ]
