        "paragraphs": [
          "Buddhasasana Home Page This document is written in Vietnamese, with Unicode Times font",
          "Kinh Pháp Cú Vietnamese translation by Bhikkhu Thích Minh Châu Sài Gòn, Việt Nam, 1996",
          "273. Of paths the Eight-fold is the best, of truths the statement Four, the passionless of teachings best, of humankind the Seer.",
          "273. Tám chánh, đường thù thắng, Bốn câu, lý thù thắng, Ly tham, pháp thù thắng, Giữa các loài hai chân, Pháp nhãn, người thù thắng.",
          "274. This is the Path, no other's there for purity of insight, enter then upon this path bemusing Mara utterly.",
          "274. Ðường này, không đường khác Ðưa đến kiến thanh tịnh. Nếu ngươi theo đường này, Ma quân sẽ mê loạn."
        ]
